def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for i in range(num_cols):
        col_values = [r[i] for r in rows if isinstance(r[i], (int, float))]
        if col_values:
            totals.append(sum(col_values))
        else:
            totals.append("")
    return totals

